create table if not exists tka_exams (exam_id uuid primary key, title text not null, jenjang text not null check (jenjang in ('MTs','MA')), subject_id text not null, status text not null default 'DRAFT', duration_seconds integer not null, timezone_name text not null default 'Asia/Jakarta', published_version integer, created_at timestamptz not null default now());
create table if not exists tka_sessions (session_id uuid primary key, exam_id uuid not null references tka_exams(exam_id), starts_at timestamptz not null, ends_at timestamptz not null, token text not null unique, created_at timestamptz not null default now());
